import { DATA_RETICLE_SOURCE_ATTR } from '@reticlehq/core';
const SOURCE_ATTR = DATA_RETICLE_SOURCE_ATTR;
export function parseSourceAttr(value) {
    if (null === value)
        return undefined;
    const m = /^(.*):(\d+):(\d+)$/.exec(value);
    if (null === m)
        return undefined;
    const file = m[1];
    const line = Number(m[2]);
    if (file === undefined || 0 === file.length || !Number.isFinite(line))
        return undefined;
    return { file, line };
}
export function sourceFromDom(el) {
    const host = el.closest(`[${SOURCE_ATTR}]`);
    return host !== null ? parseSourceAttr(host.getAttribute(SOURCE_ATTR)) : undefined;
}
export function sourceFor(el, adapterSource) {
    if (adapterSource !== undefined)
        return { file: adapterSource.file, line: adapterSource.line };
    return sourceFromDom(el);
}
export function documentHasSourceStamps(doc) {
    return doc.querySelector(`[${SOURCE_ATTR}]`) !== null;
}
export function formatSource(source) {
    return source === undefined ? undefined : `${source.file}:${String(source.line)}`;
}
